import { splitProps, type JSX, type ParentProps } from 'solid-js';
import { getInputGroupAddonStyleKeys, getInputGroupStyleKeys, inputGroupStyleKeys } from '../lib/core';
import type {
	ButtonSize,
	ButtonVariant,
	InputGroupAddonBaseProps,
	InputGroupBaseProps,
	InputGroupButtonBaseProps,
	InputGroupInputBaseProps,
	InputGroupTextareaBaseProps,
	InputGroupTextBaseProps,
} from '../lib/core';
import { composeEventHandlers } from '../lib/utils';
import styles from './input-group.module.scss';
import { Button, type ButtonProps } from '../button/button';

const INTERACTIVE_SELECTOR = 'button,a[href],input,select,textarea,summary,[contenteditable="true"],[role="button"],[role="link"],[tabindex]:not([tabindex="-1"])';

export interface InputGroupProps extends JSX.HTMLAttributes<HTMLDivElement>, InputGroupBaseProps {}

export function InputGroup(props: ParentProps<InputGroupProps>) {
	const [local, rest] = splitProps(props, ['class', 'children', 'variant']);
	const variant = () => local.variant ?? 'default';
	const styleKeys = () => getInputGroupStyleKeys(variant());
	return (
		<div {...rest} role="group" data-slot="input-group" data-variant={variant()} class={`${styles[styleKeys().base]} ${styles[styleKeys().variant]} ${local.class ?? ''}`}>
			{local.children}
		</div>
	);
}

export interface InputGroupAddonProps extends JSX.HTMLAttributes<HTMLDivElement>, InputGroupAddonBaseProps {}

export function InputGroupAddon(props: ParentProps<InputGroupAddonProps>) {
	const [local, rest] = splitProps(props, ['class', 'children', 'variant', 'align', 'onClick']);
	const variant = () => local.variant ?? 'default';
	const styleKeys = () => getInputGroupAddonStyleKeys(variant());
	const focusControl = (event: MouseEvent & { currentTarget: HTMLDivElement; target: Element }) => {
		if (event.target.closest(INTERACTIVE_SELECTOR)) return;
		event.currentTarget.parentElement?.querySelector<HTMLElement>('[data-slot="input-group-control"]')?.focus();
	};

	return (
		<div
			{...rest}
			role="group"
			data-slot="input-group-addon"
			data-variant={variant()}
			data-align={local.align ?? 'inline-start'}
			class={`${styles[styleKeys().base]} ${styles[styleKeys().variant]} ${local.class ?? ''}`}
			onClick={composeEventHandlers(local.onClick, focusControl)}>
			{local.children}
		</div>
	);
}

export interface InputGroupButtonProps extends Omit<ButtonProps, 'size' | 'variant'>, InputGroupButtonBaseProps {
	variant?: ButtonVariant;
	size?: ButtonSize;
}

export function InputGroupButton(props: ParentProps<InputGroupButtonProps>) {
	const [local, rest] = splitProps(props, ['class', 'children', 'variant', 'size', 'type']);
	return (
		<Button
			{...rest}
			type={local.type ?? 'button'}
			variant={local.variant ?? 'ghost'}
			size={local.size ?? 'sm'}
			class={`${styles[inputGroupStyleKeys.button]} ${local.class ?? ''}`}>
			{local.children}
		</Button>
	);
}

export interface InputGroupTextProps extends JSX.HTMLAttributes<HTMLSpanElement>, InputGroupTextBaseProps {}

export function InputGroupText(props: ParentProps<InputGroupTextProps>) {
	const [local, rest] = splitProps(props, ['class', 'children']);
	return (
		<span {...rest} data-slot="input-group-text" class={`${styles[inputGroupStyleKeys.text]} ${local.class ?? ''}`}>
			{local.children}
		</span>
	);
}

export interface InputGroupInputProps extends Omit<JSX.InputHTMLAttributes<HTMLInputElement>, 'size'>, InputGroupInputBaseProps {}

export function InputGroupInput(props: InputGroupInputProps) {
	const [local, rest] = splitProps(props, ['class']);
	return <input {...rest} data-slot="input-group-control" class={`${styles[inputGroupStyleKeys.input]} ${local.class ?? ''}`} />;
}

export interface InputGroupTextareaProps extends JSX.TextareaHTMLAttributes<HTMLTextAreaElement>, InputGroupTextareaBaseProps {}

export function InputGroupTextarea(props: ParentProps<InputGroupTextareaProps>) {
	const [local, rest] = splitProps(props, ['class', 'children']);
	return (
		<textarea {...rest} data-slot="input-group-control" class={`${styles[inputGroupStyleKeys.textarea]} ${local.class ?? ''}`}>
			{local.children}
		</textarea>
	);
}

export default InputGroup;

@use '../../../styles/variables/colors' as *;

.inputGroup {
	position: relative;
	display: flex;
	width: 100%;
	align-items: center;
	border-radius: var(--tile-input-group-radius, #{$radius});
	border: var(--tile-input-group-border-width, 1px) solid var(--tile-input-group-border, #{$input});
	transition:
		border-color $transition-fast,
		box-shadow $transition-fast;
	outline: none;

	&:focus-within {
		border-color: var(--tile-input-group-focus-border, #{$ring});
		box-shadow: var(--tile-input-group-focus-shadow, 0 0 0 3px color-mix(in srgb, #{$ring} 50%, transparent));
	}

	&:has([aria-invalid='true']) {
		border-color: $destructive;
		box-shadow: var(--tile-input-group-error-shadow, none);

		&:focus-within {
			box-shadow: var(--tile-input-group-error-focus-shadow, 0 0 0 3px color-mix(in srgb, #{$destructive} 20%, transparent));
		}
	}

	&:has(> textarea) {
		align-items: flex-start;
	}

	&:has(> .addon[data-align='block-start'], > .addon[data-align='block-end']) {
		flex-wrap: wrap;
	}

	// 样式变体
	&.variantDefault {
		background-color: var(--tile-input-group-background, transparent);
		box-shadow: var(--tile-input-group-shadow, #{$shadow-sm});

		&:focus-within {
			box-shadow: var(--tile-input-group-focus-shadow, #{$shadow-sm});

			&:has([aria-invalid='true']) {
				box-shadow: var(--tile-input-group-error-focus-shadow, #{$shadow-sm});
			}
		}
	}

	&.variantOutline {
		background-color: var(--tile-input-group-outline-background, #{$field-subtle});
		box-shadow: var(--tile-input-group-outline-shadow, none);

		&:focus-within {
			box-shadow: var(--tile-input-group-focus-shadow, none);

			&:has([aria-invalid='true']) {
				box-shadow: var(--tile-input-group-error-focus-shadow, none);
			}
		}
	}
}

.addon {
	display: flex;
	flex-shrink: 0;
	align-items: center;
	justify-content: center;
	gap: $spacing-2;
	cursor: text;
	padding: $spacing-1_5 0;
	font-size: $text-sm;
	font-weight: $font-medium;
	color: $muted-foreground;
	user-select: none;

	svg {
		pointer-events: none;
		width: 1rem;
		height: 1rem;
	}

	button {
		border-radius: $radius-sm;
	}

	// 样式变体
	&.variantDefault {
		background-color: var(--tile-input-group-addon-background, #{$muted});
	}

	&.variantOutline {
		background-color: transparent;
	}

	// 对齐方式
	&[data-align='inline-start'] {
		order: -1;
		padding-left: $spacing-3;
	}

	&[data-align='inline-end'] {
		order: 1;
		padding-right: $spacing-3;
	}

	&[data-align='block-start'] {
		order: -1;
		flex-basis: 100%;
		width: 100%;
		justify-content: flex-start;
		padding: $spacing-3 $spacing-3 0;

		.inputGroup:has(> input) & {
			padding-bottom: $spacing-2_5;
		}
	}

	&[data-align='block-end'] {
		order: 1;
		flex-basis: 100%;
		width: 100%;
		justify-content: flex-start;
		padding: 0 $spacing-3 $spacing-3;

		.inputGroup:has(> input) & {
			padding-top: $spacing-2_5;
		}
	}
}

.button {
	flex-shrink: 0;
	border-radius: 0;
	border: none;
	box-shadow: none;
}

.text {
	display: flex;
	flex-shrink: 0;
	align-items: center;
	gap: $spacing-2;
	font-size: $text-sm;
	color: $muted-foreground;

	svg {
		pointer-events: none;
		width: 1rem;
		height: 1rem;
	}
}

.input {
	flex: 1;
	min-width: 0;
	height: var(--tile-input-group-height, 2.25rem);
	border: none;
	background-color: transparent;
	padding: 0 $spacing-3;
	font-size: var(--tile-input-group-font-size, #{$text-sm});
	line-height: var(--tile-input-group-line-height, inherit);
	color: $foreground;
	outline: none;

	&::placeholder {
		color: $muted-foreground;
	}

	&:focus-visible {
		outline: none;
	}

	&:disabled {
		pointer-events: none;
		opacity: 0.5;
	}
}

.textarea {
	flex: 1;
	min-width: 0;
	border: none;
	background-color: transparent;
	padding: $spacing-3;
	font-size: var(--tile-input-group-font-size, #{$text-sm});
	line-height: var(--tile-input-group-line-height, inherit);
	color: $foreground;
	resize: none;
	outline: none;

	&::placeholder {
		color: $muted-foreground;
	}

	&:focus-visible {
		outline: none;
	}

	&:disabled {
		pointer-events: none;
		opacity: 0.5;
	}
}
